import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Claude Sonnet 4.6 System Card","description":"","frontmatter":{"url":"https://www.anthropic.com/claude-sonnet-4-6-system-card","title":"Claude Sonnet 4.6 System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["Anthropic"],"domains":["system-card"],"published_date":"2026-02-17T00:00:00.000Z","source_url":"https://www.anthropic.com/claude-sonnet-4-6-system-card","web_only":true},"headers":[],"relativePath":"research/papers/2026-02-17-claude-sonnet-4-6-system-card.md","filePath":"research/papers/2026-02-17-claude-sonnet-4-6-system-card.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-02-17-claude-sonnet-4-6-system-card.md"};function s(l,e,i,c,d,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="claude-sonnet-4-6-system-card" tabindex="-1">Claude Sonnet 4.6 System Card <a class="header-anchor" href="#claude-sonnet-4-6-system-card" aria-label="Permalink to &quot;Claude Sonnet 4.6 System Card&quot;">​</a></h1><p><strong>Source</strong>: Anthropic 官方 system card（web-only，無 arXiv PDF）— <a href="https://www.anthropic.com/claude-sonnet-4-6-system-card" target="_blank" rel="noreferrer">https://www.anthropic.com/claude-sonnet-4-6-system-card</a> （原始 URL 307 重導向至官方 PDF <code>www-cdn.anthropic.com/78073f739564e986ff3e28522761a7a0b4484f84.pdf</code>，內容相同。） <strong>Published</strong>: February 17, 2026</p><blockquote><p>依官方公開資訊整理；數字以可交叉驗證者為主，不確定處保守描述。</p></blockquote><hr><h2 id="摘要-依官網內容整理" tabindex="-1">摘要（依官網內容整理） <a class="header-anchor" href="#摘要-依官網內容整理" aria-label="Permalink to &quot;摘要（依官網內容整理）&quot;">​</a></h2><p>Sonnet 4.6 為高性價比 frontier 模型，coding 表現逼近同期 Opus 4.6（差距約 1.2pp），維持 Sonnet 一貫的 $3/$15 定價。安全檔位 ASL-3，並延續勒索評測 0% 的世代記錄。</p><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li><strong>Claude Sonnet 4.6</strong>：Sonnet 檔位升級，定位「best-value frontier」——近 Opus 品質、Sonnet 價格。</li></ul><h3 id="關鍵能力-安全評估數字-依官方公開資訊整理" tabindex="-1">關鍵能力 / 安全評估數字（依官方公開資訊整理） <a class="header-anchor" href="#關鍵能力-安全評估數字-依官方公開資訊整理" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字（依官方公開資訊整理）&quot;">​</a></h3><ul><li><strong>SWE-bench Verified</strong>：<strong>79.6%</strong>（10 trials 平均；距同期 Opus 4.6 的 80.8% 僅 1.2pp）。</li><li><strong>SWE-bench Multilingual</strong>：<strong>75.9%</strong>。</li><li><strong>OSWorld-Verified</strong>：<strong>72.5%</strong>（Opus 4.6 為 72.7%）。</li><li><strong>Terminal-Bench 2.0</strong>：<strong>59.1%</strong>。</li><li><strong>Pricing</strong>：<strong>$3 / 1M input、$15 / 1M output</strong>（維持 Sonnet 定價）。</li><li><strong>AI Safety Level</strong>：<strong>ASL-3</strong>。</li></ul><h3 id="值得注意章節" tabindex="-1">值得注意章節 <a class="header-anchor" href="#值得注意章節" aria-label="Permalink to &quot;值得注意章節&quot;">​</a></h3><ul><li>「near-Opus at Sonnet price」的 coding 收斂——Sonnet 與 Opus 在主流 coding/agent 評測上差距持續縮小。</li></ul><hr><h2 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h2><ul><li><strong><code>pilot</code>（tier=quality，原 <code>sonnet-pilot</code>） 強化</strong>：79.6% vs Opus 4.6 80.8% 差 1.2pp——<code>pilot</code>（tier=quality，原 <code>sonnet-pilot</code>）「接近 Opus 品質」的定位在此世代幾乎成立；多數 coding 任務可優先 Sonnet 省成本。</li><li><strong>model-selection-grid 重新校準</strong>：Sonnet/Opus 差距收斂使「10+ 檔才上 Opus」的門檻更穩固——Opus 留給真正需要 ceiling 的架構/跨模組任務。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li><strong>ASL-3 + 勒索 0%</strong>：對齊側延續穩定，sub-agent 委派的安全假設不變。</li></ul>',17)])])}const g=t(n,[["render",s]]);export{h as __pageData,g as default};
